<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>User Management · {{ config('school.name') }}</title><link rel="stylesheet" href="{{ asset('admin.css') }}"><link rel="stylesheet" href="{{ asset('admin-users.css') }}"></head><body class="mz-body"><div class="mz-layout"><aside class="mz-sidebar"><a class="mz-brand" href="{{ route('dashboard') }}"><span class="mz-logo">{{ config('school.initials') }}</span><span><strong>{{ config('school.short_name') }}</strong><small>ADMIN SEKOLAH</small></span></a><nav class="mz-nav"></nav><form method="POST" action="{{ route('logout') }}">@csrf<button class="mz-logout">Keluar dari admin</button></form></aside><main class="mz-main"><header class="mz-top"><div><p>Admin / Keamanan</p><h1>User Management</h1></div><a class="mz-button" href="{{ route('home') }}" target="_blank">Lihat website</a></header>@if(session('success'))<div class="user-alert success">{{ session('success') }}</div>@endif @if($errors->any())<div class="user-alert error">{{ $errors->first() }}</div>@endif<div class="user-grid"><section class="mz-card"><div class="user-heading"><div><h2>Daftar administrator</h2><p>Kelola akun yang dapat masuk ke dashboard.</p></div></div><div class="user-table-wrap"><table class="mz-table"><thead><tr><th>Nama</th><th>Email</th><th>Dibuat</th><th>Aksi</th></tr></thead><tbody>@foreach($users as $user)<tr><td><strong>{{ $user['name'] }}</strong>@if(session('admin_email')===$user['email']) <span class="current-badge">Akun Anda</span>@endif</td><td>{{ $user['email'] }}</td><td>{{ $user['created_at'] ?? '-' }}</td><td><button type="button" class="user-edit" data-id="{{ $user['id'] }}">Edit</button><form class="inline-form" method="POST" action="{{ route('admin.users.destroy',$user['id']) }}" onsubmit="return confirm('Hapus akun admin ini?')">@csrf @method('DELETE')<button class="user-delete" {{ count($users)<=1 || session('admin_email')===$user['email'] ? '